const root = mkdtempSync(join(tmpdir(), "bench-834-scope-"));
const git = (...args) => execFileSync("git", args, { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
const write = (path, text) => { mkdirSync(dirname(join(root, path)), { recursive: true }); writeFileSync(join(root, path), text); };
try {
  git("init", "-q");
  git("config", "user.name", "scope fixture");
  git("config", "user.email", "scope-fixture@example.invalid");
  git("config", "commit.gpgsign", "false");
  for (const path of [...allowed, "bench/budgets.json", "unexpected.txt"]) write(path, "base\n");
  git("add", ".");
  git("commit", "-qm", "base");
  const base = git("rev-parse", "HEAD");
  const guard = () => {
    assert.deepEqual(git("diff", "--name-only", base, "HEAD").split("\n").filter(Boolean).sort(), allowed);
    assert.equal(git("diff", "--name-only", "--cached"), "");
    assert.equal(git("diff", "--name-only"), "");
    assert.equal(git("status", "--porcelain"), "");
    git("diff", "--exit-code", base, "HEAD", "--", ...protectedPaths);
  };
  for (const path of allowed) write(path, "allowed\n");
