      git("reset", "--hard", good);
      write(path, "forbidden\n");
      if (state !== "unstaged") git("add", "--", path);
      if (state === "committed") git("commit", "-qm", "forbidden");
      assert.throws(guard, undefined, path + " " + state);
    }
  }
  git("reset", "--hard", good);
  write("bench/budgets.json", "protected\n");
  git("add", "--", "bench/budgets.json");
  git("restore", "--source=" + base, "--worktree", "--", "bench/budgets.json");
  assert.equal(git("diff", base, "--", "bench/budgets.json"), "");
  assert.equal(git("diff", "--name-only", "--cached"), "bench/budgets.json");
  assert.throws(guard);
  git("reset", "--hard", good);
  write("bench/budgets.json", "protected\n");
  git("add", "--", "bench/budgets.json");
  git("commit", "-qm", "protected");
  git("checkout", base, "--", "bench/budgets.json");
  git("restore", "--staged", "--", "bench/budgets.json");
  assert.equal(git("diff", base, "--", "bench/budgets.json"), "");
  assert.equal(git("diff", "--name-only", base, "HEAD", "--", "bench/budgets.json"), "bench/budgets.json");
  assert.throws(() => git("diff", "--exit-code", base, "HEAD", "--", ...protectedPaths));
  assert.throws(guard);
  console.log("scope fixture: 1 allowed pass, 6 forbidden-state rejections, 2 restored-worktree rejections; " + root);
} finally {
  rmSync(root, { recursive: true, force: true });
}
